struct Record {
    int id;
    double value;
};

// Pointer-to-member declaration
using MemberPtr = double Record::*;

// Capture offset of 'value'
MemberPtr p_value = &Record::value;

Record r {101, 42.7};

// Access via runtime offset calculation
double result = r.*p_value; // Result is 42.7
